import { Identifier } from "../../core/utils/Identifier";
import { Item } from "../utils/holder/Item";

export type JsonValue =
    | string
    | number
    | boolean
    | null
    | JsonValue[]
    | { [key: string]: JsonValue };

export type JsonObject = { [key: string]: JsonValue };

/** Componentes padrão dos itens da 26.3. */
export interface ItemComponents {
    "minecraft:attack_animation": JsonObject;
    "minecraft:attack_range": JsonObject;
    "minecraft:attribute_modifiers": JsonValue[];
    "minecraft:banner_patterns": JsonValue[];
    "minecraft:bees": JsonValue[];
    "minecraft:block_state": JsonObject;
    "minecraft:block_transformer": "minecraft:axe" | "minecraft:hoe" | "minecraft:shovel";
    "minecraft:blocks_attacks": JsonObject;
    "minecraft:break_sound": "minecraft:entity.item.break" | "minecraft:item.shield.break" | "minecraft:item.wolf_armor.break";
    "minecraft:brewing_fuel": JsonObject;
    "minecraft:bucket_entity_data": JsonObject;
    "minecraft:bundle_contents": JsonValue[];
    "minecraft:charged_projectiles": JsonValue[];
    "minecraft:chicken/variant": "minecraft:cold" | "minecraft:temperate" | "minecraft:warm";
    "minecraft:compostable": JsonObject;
    "minecraft:consumable": JsonObject;
    "minecraft:container": JsonValue[];
    "minecraft:cooking_fuel": JsonObject;
    "minecraft:cushion/color": "black" | "blue" | "brown" | "cyan" | "gray" | "green" | "light_blue" | "light_gray" | "lime" | "magenta" | "orange" | "pink" | "purple" | "red" | "white" | "yellow";
    "minecraft:damage": number;
    "minecraft:damage_resistant": JsonObject;
    "minecraft:damage_type": string;
    "minecraft:death_protection": JsonObject;
    "minecraft:debug_stick_state": JsonObject;
    "minecraft:dye": "black" | "blue" | "brown" | "cyan" | "gray" | "green" | "light_blue" | "light_gray" | "lime" | "magenta" | "orange" | "pink" | "purple" | "red" | "white" | "yellow";
    "minecraft:enchantable": JsonObject;
    "minecraft:enchantment_glint_override": boolean;
    "minecraft:enchantments": JsonObject;
    "minecraft:entity_data": JsonObject;
    "minecraft:equippable": JsonObject;
    "minecraft:fireworks": JsonObject;
    "minecraft:food": JsonObject;
    "minecraft:glider": JsonObject;
    "minecraft:instrument": string;
    "minecraft:interact_animation": JsonObject;
    "minecraft:item_model": string;
    "minecraft:item_name": JsonObject;
    "minecraft:jukebox_playable": string;
    "minecraft:kinetic_weapon": JsonObject;
    "minecraft:lore": JsonValue[];
    "minecraft:map_decorations": JsonObject;
    "minecraft:max_damage": number;
    "minecraft:max_stack_size": number;
    "minecraft:minimum_attack_charge": number;
    "minecraft:mob_visibility": JsonObject;
    "minecraft:ominous_bottle_amplifier": number;
    "minecraft:piercing_weapon": JsonObject;
    "minecraft:pot_decorations": JsonObject;
    "minecraft:potion_contents": JsonObject;
    "minecraft:potion_duration_scale": number;
    "minecraft:provides_banner_patterns": "#minecraft:pattern_item/bordure_indented" | "#minecraft:pattern_item/creeper" | "#minecraft:pattern_item/field_masoned" | "#minecraft:pattern_item/flow" | "#minecraft:pattern_item/flower" | "#minecraft:pattern_item/globe" | "#minecraft:pattern_item/guster" | "#minecraft:pattern_item/mojang" | "#minecraft:pattern_item/piglin" | "#minecraft:pattern_item/skull";
    "minecraft:provides_pottery_pattern": string;
    "minecraft:provides_trim_material": "minecraft:amethyst" | "minecraft:copper" | "minecraft:diamond" | "minecraft:emerald" | "minecraft:gold" | "minecraft:iron" | "minecraft:lapis" | "minecraft:netherite" | "minecraft:quartz" | "minecraft:redstone" | "minecraft:resin";
    "minecraft:rarity": "common" | "epic" | "rare" | "uncommon";
    "minecraft:recipes": JsonValue[];
    "minecraft:repair_cost": number;
    "minecraft:repairable": JsonObject;
    "minecraft:sign_text_back": JsonObject;
    "minecraft:sign_text_front": JsonObject;
    "minecraft:stored_enchantments": JsonObject;
    "minecraft:suspicious_stew_effects": JsonValue[];
    "minecraft:tool": JsonObject;
    "minecraft:tooltip_display": JsonObject;
    "minecraft:use_cooldown": JsonObject;
    "minecraft:use_effects": JsonObject;
    "minecraft:use_remainder": JsonObject;
    "minecraft:villager_food": JsonObject;
    "minecraft:weapon": JsonObject;
    "minecraft:writable_book_content": JsonObject;
}

